mapper.select:
SELECT combo.user_id AS user_id, SUM(combo.lots_remaining) AS lots_remaining, SUM(combo.ledger_total) AS ledger_total FROM ( SELECT l.user_id AS user_id, SUM(l.remaining) AS lots_remaining, 0 AS ledger_total FROM billing_credit_lots l GROUP BY l.user_id
UNION ALL
SELECT e.user_id AS user_id, 0 AS lots_remaining, SUM(e.balance_after) AS ledger_total FROM billing_ledger_entries e JOIN () latest ON e.id = latest.max_id GROUP BY e.user_id ) combo GROUP BY combo.user_id HAVING lots_remaining <> ledger_total ORDER BY ABS(SUM(combo.lots_remaining) - SUM(combo.ledger_total)) DESC, combo.user_id ASC LIMIT #{limit}
